INSERT INTO philanthropic_gifts (id,grantor_name,donor_line,donor_type,total_committed,state_code,geo_scope,grant_amount,amount_display,req_no_seed,req_has_seed,req_age_max,req_born_year_min,req_born_year_max,req_zip_income,income_cap,req_zip_set,req_checkbox_labels,note,source_url,sort_order,is_open_to_apply) VALUES ('shotwell_spacex_stock','Gwynne Shotwell','SpaceX President & COO — personal pledge of SpaceX stock, announced July 2026','individual',NULL,NULL,'closed',NULL,'TBD (SpaceX stock share)',0,0,NULL,NULL,NULL,0,NULL,NULL,NULL,'Gwynne Shotwell and her husband pledged a share of their personal SpaceX stock to Trump Accounts for more than 2 million children nationwide via the Invest America program. Targeted at children ages 11-17 in areas with lower average household income, with added emphasis for those near Shotwell''s central Texas home. No fixed per-child dollar amount, structured application, or formal eligibility criteria published — informational only.','https://x.com/Gwynne_Shotwell/status/2074064376810614926',130,0);